import {createHash} from 'node:crypto';
import {isDeepStrictEqual} from 'node:util';
export const digest=x=>createHash('sha256').update(JSON.stringify(x)).digest('hex');
const copy=x=>JSON.parse(JSON.stringify(x));
const check=(x,m)=>{if(!x)throw Error(m);};
export class ContinuityRouter {
 constructor({ledger,duty,members,verifyPriority=()=>false,verifyContinuity=()=>false}){this.ledger=ledger;this.duty=duty;this.verifyPriority=verifyPriority;this.verifyContinuity=verifyContinuity;const roster=duty.snapshot().members;check(Array.isArray(members)&&members.length===Object.keys(roster).length,'exact roster');for(const field of ['actorId','sessionId'])check(new Set(members.map(m=>m[field])).size===members.length,'unique roster');for(const m of members)check(roster[m.actorId]?.sessionId===m.sessionId&&m.body.actorId===m.actorId&&m.body.sessionId===m.sessionId,'same pinned Body identity');this.members=new Map(members.map(m=>[m.actorId,m]));}
 save(kind,id,value){const old=this.ledger.one(kind,id);check(!old||digest(old)===digest(value),'immutable record conflict');if(!old)this.ledger.tx(()=>this.ledger.put(kind,id,value));return copy(value);}
 own(ref){check(ref&&Object.keys(ref).sort().join(',')==='actorId,rawDigest,sessionId,sourceId,ticketId','exact source reference');const m=this.members.get(ref.actorId);check(m&&m.sessionId===ref.sessionId,'source identity');const s=m.body.one('source',ref.sourceId);check(s?.kind==='completed'&&s.ticketId===ref.ticketId&&m.body.one('processed',s.ticketId)?.sourceId===ref.sourceId,'accepted source required');check(s.provenance?.sessionId===m.sessionId&&Number.isSafeInteger(s.provenance.assistantSeq)&&s.provenance.assistantSeq>=0&&s.provenance.endSeq>s.provenance.assistantSeq&&s.provenance.boundary===s.provenance.endSeq+1&&ref.sourceId==='completed:'+digest([m.sessionId,s.provenance.assistantSeq])&&digest(s.raw)===ref.rawDigest&&digest(JSON.parse(s.raw))===digest(s.choice),'exact raw provenance');const b=m.body.binding(s.ticketId);check(b?.actorId===m.actorId&&b.sessionId===m.sessionId&&m.body.one('ack',s.ticketId)?.queued===true&&m.body.one('stream',s.ticketId)?.sessionId===m.sessionId,'source admission');check(s.choice.meeting.kind==='contribute','explicit public contribution required');let record;try{record=JSON.parse(s.choice.meeting.text);}catch{throw Error('typed public record required');}return{record,ref:copy(ref),publicText:s.choice.meeting.text,provenance:copy(s.provenance)};}
 freeze({roundId,sharedEpoch,sharedRefs,topic,urgent=false}){check(typeof roundId==='string'&&roundId&&Number.isSafeInteger(sharedEpoch)&&sharedEpoch>=0&&Array.isArray(sharedRefs)&&typeof topic==='string'&&topic&&typeof urgent==='boolean','round fields');check(sharedRefs.every(r=>r&&typeof r.id==='string'&&r.id&&/^[a-f0-9]{64}$/.test(r.digest))&&new Set(sharedRefs.map(r=>r.id)).size===sharedRefs.length,'unique shared references');const snapshot={roundId,roster:[...this.members.values()].map(({actorId,sessionId})=>({actorId,sessionId})),sharedEpoch,sharedRefs:copy(sharedRefs),topic,urgent};return this.save('assembly-snapshot',roundId,{...snapshot,snapshotDigest:digest(snapshot)});}
 state(roundId){const snapshot=this.ledger.one('assembly-snapshot',roundId);check(snapshot,'unknown round');return{snapshot,terminal:this.ledger.one('assembly-terminal',roundId),priority:this.ledger.rows('assembly-priority').filter(r=>r.data.roundId===roundId).map(r=>r.data)};}
 snapshot(roundId){return copy(this.state(roundId).snapshot);}
 input(actorId,roundId){const s=this.state(roundId);check(this.members.has(actorId),'unknown actor');check(!s.terminal,'round not open');return copy(s.snapshot);}
 stage(ref){const own=this.own(ref),r=own.record;check(r.kind==='position'&&['support','oppose','silent','undecided','conditional','decline'].includes(r.position)&&typeof r.text==='string'&&r.text.trim()&&(r.reason===null||typeof r.reason==='string'),'explicit opinion');const s=this.state(r.roundId);check(!s.terminal,'round not open');check(r.snapshotDigest===s.snapshot.snapshotDigest,'wrong shared snapshot');const m=this.members.get(ref.actorId),b=m.body.binding(ref.ticketId);check(Array.isArray(b.content)&&b.content.length===1,'bound input');const bound=JSON.parse(b.content[0].text);check(digest(bound.sharedContext?.assembly)===digest(s.snapshot),'snapshot not offered in exact bound input');const key=digest([r.roundId,ref.actorId,ref.sourceId]);return this.save('assembly-staged',key,{roundId:r.roundId,actorId:ref.actorId,sessionId:ref.sessionId,record:r,source:own.ref,publicText:own.publicText,provenance:own.provenance});}
 publish(roundId,{boundaryId}){const s=this.state(roundId);check(typeof boundaryId==='string'&&boundaryId,'boundary required');const prior=this.ledger.one('assembly-release',roundId);if(prior){check(prior.boundaryId===boundaryId,'release boundary conflict');return copy(prior);}check(!s.terminal,'round not open');const opinions=this.ledger.rows('assembly-staged').filter(r=>r.data.roundId===roundId).map(r=>r.data);const responded=new Set(opinions.map(o=>o.actorId));const release={roundId,snapshotDigest:s.snapshot.snapshotDigest,boundaryId,opinions,missing:s.snapshot.roster.filter(m=>!responded.has(m.actorId)).map(m=>({...m,status:'no-accepted-opinion',reason:null})),executionAuthorized:false};this.ledger.tx(()=>{this.ledger.put('assembly-release',roundId,release);this.ledger.put('assembly-terminal',roundId,{status:'published-observation',boundaryId});});return copy(release);}
 publicView(roundId){this.state(roundId);return copy(this.ledger.one('assembly-release',roundId)??{roundId,status:'unpublished',opinions:[]});}
 priority(roundId,{messageId,type,evidence}){check(['authenticated-owner','evidenced-historian','evidenced-resource'].includes(type),'qualifying priority kind');check(this.verifyPriority({roundId,messageId,type,evidence})===true,'priority evidence not authenticated/validated');const s=this.state(roundId);const old=this.ledger.one('assembly-priority',messageId);if(old){check(old.roundId===roundId&&old.type===type&&digest(old.evidence)===digest(evidence),'priority ID conflict');return copy(old);}check(!s.terminal,'round not open');const result={roundId,messageId,type,evidence:copy(evidence),status:s.snapshot.urgent?'urgent-policy-held':'terminated-for-priority',executionAuthorized:false};this.ledger.tx(()=>{this.ledger.put('assembly-priority',messageId,result);this.ledger.put('assembly-terminal',roundId,{status:result.status,messageId});});return copy(result);}
 invalidatePriority(messageId,{evidence}){const old=this.ledger.one('assembly-priority',messageId);check(old,'unknown priority message');check(this.verifyPriority({roundId:old.roundId,messageId,type:'evidence-invalidation',evidence})===true,'unverified evidence invalidation');return this.save('assembly-priority-invalidation',messageId,{messageId,roundId:old.roundId,evidence:copy(evidence),status:'retain-termination-or-hold-pending-review',automaticReopen:false});}
 proposeDuty(id,{role,successor,now,rotationDueAt,crashed=false,crashEvidence=null}){const member=this.members.get(successor);check(member,'unknown successor');const old=this.ledger.one('continuity-handoff',id);if(old){check(old.role===role&&old.successor===successor&&old.now===now&&old.rotationDueAt===rotationDueAt&&old.crashed===crashed&&digest(old.crashEvidence)===digest(crashEvidence),'handoff ID conflict');return copy(old);}check(this.verifyContinuity({id,role,successor,now,rotationDueAt,crashed,crashEvidence})===true,'continuity eligibility/evidence policy unresolved');if(crashed)check(crashEvidence?.reference&&crashEvidence.deliveryOutcome!=='unknown','crash evidence or external delivery reconciliation missing');const intent={role,successor,now,rotationDueAt,crashed,crashEvidence};this.save('continuity-handoff-intent',id,intent);if(crashed)this.duty.hold('crash-hold:'+id,{role,reason:'no-successor',now});if(member.body.state().mode!=='awake'){return this.save('continuity-handoff',id,{...intent,status:'successor-unavailable',wakeIntent:{actorId:member.actorId,sessionId:member.sessionId,status:'pending-eligibility-and-authorized-wake-adapter',dispatched:false},escalation:'unresolved-continuity'});}const p=this.duty.propose('proposal:'+id,{role,successor,eligibleSessionId:member.sessionId,now,rotationDueAt});return this.save('continuity-handoff',id,{...intent,status:'awaiting-successor-own-record',proposal:p,escalation:crashed?'incomplete-handoff-continuity-problem':null});}
 acceptDuty(id,ref,{now}){const p=this.ledger.one('continuity-handoff',id);check(p?.status==='awaiting-successor-own-record','no admitted handoff');const own=this.own(ref),r=own.record;check(ref.actorId===p.successor&&r.kind==='duty-ack'&&r.proposalId===p.proposal.handoff.proposalId&&r.role===p.role&&r.epoch===p.proposal.bundle.epoch&&r.pendingDigest===p.proposal.handoff.bundleDigest,'successor own acknowledgement mismatch');const binding=this.members.get(ref.actorId).body.binding(ref.ticketId);const payload=JSON.parse(binding.content[0].text);check(digest(payload.sharedContext?.handoff)===digest(p),'handoff not offered in exact bound input');const receipt={id,source:own.ref,role:p.role,successor:p.successor,now,incompleteHandoff:p.crashed,outgoingOwnRecordPresent:false};const prior=this.ledger.one('continuity-ack',id);if(prior){check(digest(prior)===digest(receipt),'ack identity conflict');return copy(prior);}const operationId='own-ack:'+id;
  const operationInput={role:p.role,proposalId:r.proposalId,actorId:ref.actorId,sessionId:ref.sessionId,bundleDigest:r.pendingDigest,now};
  const operation=this.duty.ledger.one('duty-operation',operationId);
  if(operation){
   const intent=this.ledger.one('continuity-ack-intent',id);
   check(intent&&isDeepStrictEqual(intent,receipt),'committed ack original intent mismatch');
   check(operation.inputHash===digest(operationInput),'committed ack operation input hash mismatch');
   const expected={epoch:p.proposal.bundle.epoch+1,actorId:ref.actorId,status:'staffed',rotationDueAt:p.rotationDueAt,lastAssignedActor:ref.actorId,assignedAt:now,handoff:null};
   check(isDeepStrictEqual(operation.result,expected),'committed ack operation result mismatch');
   const committedState=this.duty.ledger.one('duty-state',operationId);
   check(committedState&&isDeepStrictEqual(committedState.roles?.[p.role],expected),'committed ack state mismatch');
   // Receipt-only repair: never reassign, wake, inspect present tenure as old tenure,
   // or move the durable clock. A later sleep/stop/epoch is not the old outcome.
   return this.save('continuity-ack',id,receipt);
  }
  check(this.members.get(ref.actorId).body.state().mode==='awake','successor not awake after acknowledgement');
  this.save('continuity-ack-intent',id,receipt);
  this.duty.acknowledgeHandoff(operationId,operationInput);
  return this.save('continuity-ack',id,receipt);}
}
